CREATE TABLE institutional_eligibility_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL, source_id uuid NOT NULL, readiness_score integer NOT NULL DEFAULT 0, eligibility_state text NOT NULL DEFAULT 'not_ready', satisfied_count integer NOT NULL DEFAULT 0, required_count integer NOT NULL DEFAULT 0, gaps jsonb NOT NULL DEFAULT '[]'::jsonb, actions jsonb NOT NULL DEFAULT '[]'::jsonb, assessed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,source_id));